{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Doxazosin, a 2,4-diamino-6,7-dimethoxyquinazoline closely related to the query core, has an absolute oral bioavailability of 65 ± 14% in young volunteers, supporting a high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Bunazosin, another 2,4-diamino-6,7-dimethoxyquinazoline with a basic N-acyl homopiperazine substituent, has an absolute oral bioavailability of 44.1%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Trimazosin, sharing the same quinazoline core with a piperazine carbamate, has an oral bioavailability of 61 ± 28%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Vismodegib, which shares the 2-pyridyl and sulfonamide motifs present in the query, has an absolute oral bioavailability of 31.8%, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Tariquidar, a larger tetrahydroisoquinoline-containing compound, has low oral bioavailability in humans; this is a contradictory data point but has limited transferability to the smaller quinazoline query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 2,4-diamino-6,7-dimethoxyquinazoline; direct quinazoline analogues (doxazosin, bunazosin, trimazosin) all show absolute oral bioavailability well above 20% (44-65%). The only low-F analogue (tariquidar) is much larger and less transferable. Therefore predict high.",
  "evidence_gaps": [
    "No direct experimental F measurement for the exact query or a close analogue with the 5-(2-pyridyl) and tetrahydroisoquinoline-sulfonamide substituents.",
    "Potential effects of the 5-pyridyl and methanesulfonamide groups on solubility, permeability, or efflux are not directly quantified by the retrieved analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

